mapper.select:
SELECT 'knowledge' AS module, id, knowledge_name AS title, LEFT(knowledge_content, 200) AS snippet_raw, DATE_FORMAT(update_time, '%Y-%m-%d %H:%i') AS update_time FROM t_knowledge
(knowledge_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/' OR knowledge_content LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/')
ORDER BY update_time DESC LIMIT #{limit}

SELECT 'navigation' AS module, id, navigation_name AS title, CONCAT_WS(' · ', `desc`, tag) AS snippet_raw, DATE_FORMAT(update_time, '%Y-%m-%d %H:%i') AS update_time FROM t_navigation
(navigation_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/' OR `desc` LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/' OR tag LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/')
ORDER BY update_time DESC LIMIT #{limit}

SELECT 'plan' AS module, id, plan_name AS title, LEFT(plan_desc, 200) AS snippet_raw, DATE_FORMAT(update_time, '%Y-%m-%d %H:%i') AS update_time FROM t_gantt_plan
del_flag = '0'
AND create_by = #{ownerId}
AND (plan_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/' OR plan_desc LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/')
ORDER BY update_time DESC LIMIT #{limit}

SELECT 'task' AS module, t.id, t.task_name AS title, CONCAT('计划：', p.plan_name, ' ｜ ', LEFT(t.task_desc, 160)) AS snippet_raw, DATE_FORMAT(t.update_time, '%Y-%m-%d %H:%i') AS update_time FROM t_gantt_task t JOIN t_gantt_plan p ON p.id = t.plan_id AND p.del_flag = '0'
t.del_flag = '0'
AND p.create_by = #{ownerId}
AND (t.task_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/' OR t.task_desc LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/')
ORDER BY t.update_time DESC LIMIT #{limit}
